-- ============================================================================
-- 后置自检：演示面非空 + 系统种子面未被本册触碰
-- ============================================================================
DO $$
DECLARE
    v_n BIGINT;
    v_msg TEXT := '';
BEGIN
    SELECT count(*) INTO v_n FROM ecos_control.ecos_business_scenario;
    IF v_n = 0 THEN RAISE EXCEPTION 'ecos_business_scenario 为空 ⇒ 场景工作台无内容'; END IF;
    v_msg := v_msg || 'scenario=' || v_n;
    SELECT count(*) INTO v_n FROM ecos_control.ecos_ontology_entity;
    IF v_n = 0 THEN RAISE EXCEPTION 'ecos_ontology_entity 为空 ⇒ 本体面无内容'; END IF;
    v_msg := v_msg || ' ontology_entity=' || v_n;
    SELECT count(*) INTO v_n FROM ecos_knowledge.kb_doc;
    IF v_n = 0 THEN RAISE EXCEPTION 'kb_doc 为空 ⇒ 文档接入记录面无内容（注意：知识总览 6 KPI 读的是 knowledge_article/graph_node/graph_edge/knowledge_embedding，不读本表）'; END IF;
    v_msg := v_msg || ' kb_doc=' || v_n;
    SELECT count(*) INTO v_n FROM ecos_data.ecos_pipeline_definition;
    IF v_n = 0 THEN RAISE EXCEPTION 'ecos_pipeline_definition 为空 ⇒ 管道面无内容'; END IF;
    v_msg := v_msg || ' pipeline_def=' || v_n;
    -- 系统种子面必须仍在（本册与它表级互斥，不得把它清掉或覆盖）
    SELECT count(*) INTO v_n FROM ecos_control.td_user;
    IF v_n = 0 THEN RAISE EXCEPTION 'td_user 为空 ⇒ 系统种子面被破坏'; END IF;
    v_msg := v_msg || ' td_user=' || v_n;
    SELECT count(*) INTO v_n FROM ecos_control.sys_config;
    IF v_n = 0 THEN RAISE EXCEPTION 'sys_config 为空 ⇒ 系统种子面被破坏'; END IF;
    v_msg := v_msg || ' sys_config=' || v_n;
    RAISE NOTICE 'demo_seed 自检通过：%', v_msg;
END $$;

\if :{?ecos_commit}
    \if :ecos_commit
        COMMIT;
        \echo 'demo_seed 已提交（ecos_commit=1）'
    \else
        ROLLBACK;
        \echo 'demo_seed 已回滚（dry-run，未传 ecos_commit=1）'
    \endif
\else
    ROLLBACK;
    \echo 'demo_seed 已回滚（dry-run，未传 ecos_commit=1）'
\endif
