INSERT INTO ecos_ai.ecos_agent_registry (id, name, role, capability, status, endpoint, metadata, tenant_id, created_at, updated_at) SELECT 'builtin-ai-agent', 'AI编排Agent', 'builtin', '{"tools": ["delegate_to_agent"]}', 'INACTIVE', NULL, '{"model": "deepseek-chat", "modelName": "deepseek-chat", "description": "ECOS 内置 AI 编排 Agent，负责多 Agent 委托调度和 Agent 元信息查询。", "temperature": 0.1, "systemPrompt": "你是 ECOS AI 引擎的编排助手，负责协调多个子 Agent 完成复杂任务。你能够将用户任务拆解为子任务并委托给合适的 Agent 执行，也能够查询所有已注册 Agent 的元信息以辅助决策。", "maxIterations": 5, "modelProvider": "deepseek"}', NULL, '2026-11-10 16:17:49.299283', '2026-11-10 17:40:27.634542' WHERE NOT EXISTS (SELECT 1 FROM ecos_ai.ecos_agent_registry WHERE id = 'builtin-ai-agent');
